<?php
namespace App\Http\Controllers\Api\Hr;
use App\Http\Controllers\Controller;use App\Models\Staff;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class ServiceOperationsController extends Controller{
 public function claims(Request$r):JsonResponse{$a=$this->actor($r);$q=DB::table('hr_expense_claims')->where('company_id',$a->company_id);if(!$r->user()->can('hr.expenses.view-all'))$q->where('staff_id',$a->id);return response()->json(['status'=>'success','data'=>$q->latest()->paginate($r->integer('per_page',50))]);}
 public function storePolicy(Request$r):JsonResponse{$this->enabled();$d=$r->validate(['company_id'=>['required','uuid'],'code'=>['required','string','max:80'],'version'=>['required','integer','min:1'],'rules'=>['required','array'],'effective_from'=>['required','date'],'effective_until'=>['nullable','date','after_or_equal:effective_from']]);$this->company($r,$d['company_id']);$id=(string)Str::uuid();$d['rules']=json_encode($d['rules'],JSON_THROW_ON_ERROR);DB::table('hr_expense_policy_versions')->insert($d+['id'=>$id,'status'=>'pending_approval','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_expense_policy_versions')->find($id)],201);}
 public function approvePolicy(Request$r,string$id):JsonResponse{$this->enabled();return DB::transaction(function()use($r,$id){$p=DB::table('hr_expense_policy_versions')->where('id',$id)->lockForUpdate()->first();abort_unless($p,404);$this->company($r,$p->company_id);abort_unless($p->status==='pending_approval',409);abort_if($p->created_by===$r->user()->id,409,'Policy creator cannot approve the same version.');DB::table('hr_expense_policy_versions')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_expense_policy_versions')->find($id)]);});}
 public function submitClaim(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['policy_version_id'=>['required','uuid'],'claim_number'=>['required','string','max:80'],'claim_type'=>['required',Rule::in(['expense','travel','mileage','advance_liquidation'])],'currency'=>['required','string','size:3'],'allocation_snapshot'=>['required','array'],'lines'=>['required','array','min:1','max:200'],'lines.*.category_code'=>['required','string','max:80'],'lines.*.expense_date'=>['required','date'],'lines.*.description'=>['required','string','max:500'],'lines.*.amount'=>['required','numeric','min:0.01'],'lines.*.fx_rate'=>['nullable','numeric','gt:0'],'lines.*.base_amount'=>['required','numeric','min:0.01'],'lines.*.merchant_fingerprint'=>['nullable','string','max:160'],'lines.*.receipt_checksum'=>['nullable','string','size:64'],'lines.*.tax_snapshot'=>['nullable','array']]);$policy=DB::table('hr_expense_policy_versions')->where('id',$d['policy_version_id'])->where('company_id',$a->company_id)->where('status','approved')->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->first();abort_unless($policy,422,'An effective approved expense policy is required.');$checksum=hash('sha256',json_encode($d,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));if($existing=DB::table('hr_expense_claims')->where('content_checksum',$checksum)->where('staff_id',$a->id)->first())return response()->json(['status'=>'success','data'=>$existing,'idempotent_replay'=>true]);foreach($d['lines'] as$line)if(!empty($line['receipt_checksum'])&&DB::table('hr_expense_lines as l')->join('hr_expense_claims as c','c.id','=','l.claim_id')->where('c.company_id',$a->company_id)->where('l.receipt_checksum',$line['receipt_checksum'])->whereNotIn('c.status',['rejected','cancelled'])->exists())abort(409,'A receipt is already attached to another active claim.');$id=(string)Str::uuid();$total=array_sum(array_map(fn($line)=>(float)$line['base_amount'],$d['lines']));DB::transaction(function()use($r,$a,$d,$id,$total,$checksum){DB::table('hr_expense_claims')->insert(['id'=>$id,'company_id'=>$a->company_id,'staff_id'=>$a->id,'policy_version_id'=>$d['policy_version_id'],'claim_number'=>$d['claim_number'],'claim_type'=>$d['claim_type'],'currency'=>strtoupper($d['currency']),'claimed_amount'=>$total,'status'=>'pending_approval','allocation_snapshot'=>json_encode($d['allocation_snapshot'],JSON_THROW_ON_ERROR),'content_checksum'=>$checksum,'submitted_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines']as$line){$line['id']=(string)Str::uuid();$line['claim_id']=$id;if(isset($line['tax_snapshot']))$line['tax_snapshot']=json_encode($line['tax_snapshot'],JSON_THROW_ON_ERROR);$line['created_at']=$line['updated_at']=now();DB::table('hr_expense_lines')->insert($line);}$this->claimEvent($id,'submitted',null,'pending_approval',['claimed_amount'=>$total],$r->user()->id);});return response()->json(['status'=>'success','data'=>DB::table('hr_expense_claims')->find($id)],201);}
 public function decideClaim(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'approved_amount'=>['nullable','numeric','min:0'],'reason'=>['required','string','max:2000']]);return DB::transaction(function()use($r,$id,$d){$c=DB::table('hr_expense_claims')->where('id',$id)->lockForUpdate()->first();abort_unless($c,404);$this->company($r,$c->company_id);abort_unless($c->status==='pending_approval',409);abort_if($c->submitted_by===$r->user()->id,409,'Claim submitter cannot approve the same claim.');$amount=$d['decision']==='approved'?($d['approved_amount']??$c->claimed_amount):null;abort_if($amount!==null&&(float)$amount>(float)$c->claimed_amount,422,'Approved amount cannot exceed claimed amount.');DB::table('hr_expense_claims')->where('id',$id)->update(['status'=>$d['decision'],'approved_amount'=>$amount,'decision_reason'=>$d['reason'],'approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);$this->claimEvent($id,$d['decision'],$c->status,$d['decision'],['approved_amount'=>$amount,'reason'=>$d['reason']],$r->user()->id);if($d['decision']==='approved'){$payload=['claim_id'=>$id,'staff_id'=>$c->staff_id,'amount'=>$amount,'currency'=>$c->currency,'allocation_snapshot'=>json_decode($c->allocation_snapshot,true)];DB::table('hr_accounting_outbox')->insert(['id'=>(string)Str::uuid(),'company_id'=>$c->company_id,'event_type'=>'expense_claim_approved','aggregate_type'=>'expense_claim','aggregate_id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'status'=>'pending','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}return response()->json(['status'=>'success','data'=>DB::table('hr_expense_claims')->find($id)]);});}
 public function tickets(Request$r):JsonResponse{$a=$this->actor($r);$q=DB::table('hr_service_requests')->where('company_id',$a->company_id);if(!$r->user()->can('hr.service-desk.view-all'))$q->where(fn($b)=>$b->where('staff_id',$a->id)->orWhere('assigned_staff_id',$a->id));return response()->json(['status'=>'success','data'=>$q->select(['id','request_number','staff_id','catalog_code','priority','confidentiality','status','subject','assigned_staff_id','due_at','resolved_at'])->latest()->paginate($r->integer('per_page',50))]);}
 public function openTicket(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['request_number'=>['required','string','max:80'],'catalog_code'=>['required','string','max:80'],'priority'=>['required',Rule::in(['low','normal','high','urgent'])],'confidentiality'=>['required',Rule::in(['standard','restricted'])],'subject'=>['required','string','max:500'],'details'=>['required','string','max:10000'],'due_at'=>['nullable','date']]);$id=(string)Str::uuid();DB::table('hr_service_requests')->insert(['id'=>$id,'company_id'=>$a->company_id,'staff_id'=>$a->id,'request_number'=>$d['request_number'],'catalog_code'=>$d['catalog_code'],'priority'=>$d['priority'],'confidentiality'=>$d['confidentiality'],'status'=>'open','subject'=>$d['subject'],'encrypted_details'=>encrypt($d['details']),'due_at'=>$d['due_at']??null,'created_at'=>now(),'updated_at'=>now()]);$this->ticketEvent($id,'opened',null,'open',null,$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_service_requests')->select(['id','request_number','status','subject','priority','due_at'])->find($id)],201);}
 public function transitionTicket(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['to'=>['required',Rule::in(['assigned','in_progress','waiting_employee','resolved','closed','reopened'])],'assigned_staff_id'=>['nullable','uuid'],'note'=>['required','string','max:4000']]);return DB::transaction(function()use($r,$id,$d){$t=DB::table('hr_service_requests')->where('id',$id)->lockForUpdate()->first();abort_unless($t,404);$this->company($r,$t->company_id);$allowed=['open'=>['assigned','in_progress'],'assigned'=>['in_progress'],'in_progress'=>['waiting_employee','resolved'],'waiting_employee'=>['in_progress','resolved'],'resolved'=>['closed','reopened'],'reopened'=>['assigned','in_progress']];abort_unless(in_array($d['to'],$allowed[$t->status]??[],true),409,'Invalid service request transition.');if(isset($d['assigned_staff_id']))abort_unless(Staff::query()->whereKey($d['assigned_staff_id'])->where('company_id',$t->company_id)->exists(),422);DB::table('hr_service_requests')->where('id',$id)->update(['status'=>$d['to'],'assigned_staff_id'=>$d['assigned_staff_id']??$t->assigned_staff_id,'resolved_at'=>$d['to']==='resolved'?now():null,'updated_at'=>now()]);$this->ticketEvent($id,'status_changed',$t->status,$d['to'],$d['note'],$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_service_requests')->select(['id','request_number','status','assigned_staff_id','due_at','resolved_at'])->find($id)]);});}
 private function claimEvent(string$id,string$type,?string$from,?string$to,array$e,string$actor):void{DB::table('hr_expense_claim_events')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'evidence'=>json_encode($e,JSON_THROW_ON_ERROR),'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function ticketEvent(string$id,string$type,?string$from,?string$to,?string$note,string$actor):void{DB::table('hr_service_request_events')->insert(['id'=>(string)Str::uuid(),'service_request_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'encrypted_note'=>$note?encrypt($note):null,'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function company(Request$r,string$id):void{abort_unless($this->actor($r)->company_id===$id,403,'HR service data is outside your legal entity.');}private function enabled():void{abort_unless(config('hr.features.service_operations',false),409,'HR service operations writes are not enabled.');}
}
